index|documentTag_tag|documentTag|CREATE INDEX documentTag_tag ON documentTag(tagId)
index|document_category|document|CREATE INDEX document_category ON document(categoryId)
index|highlightTag_tag|highlightTag|CREATE INDEX highlightTag_tag ON highlightTag(tagId)
index|highlight_document|highlight|CREATE INDEX highlight_document ON highlight(documentId, positionKey)
index|reviewCard_due|reviewCard|CREATE INDEX reviewCard_due ON reviewCard(dueAt) WHERE suspended = 0
index|reviewCard_highlight|reviewCard|CREATE INDEX reviewCard_highlight ON reviewCard(highlightId)
index|reviewLog_card|reviewLog|CREATE INDEX reviewLog_card ON reviewLog(cardId, reviewedAt)
index|reviewLog_themedReview|reviewLog|CREATE INDEX reviewLog_themedReview ON reviewLog(themedReviewId)
table|category|category|CREATE TABLE category ( id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, isBuiltin INTEGER NOT NULL DEFAULT 0, frequency TEXT NOT NULL DEFAULT 'normal' CHECK (frequency IN ('off','low','normal','high')), autoCreateCards INTEGER NOT NULL DEFAULT 1, sortOrder INTEGER NOT NULL DEFAULT 0 )
table|document|document|CREATE TABLE document ( id TEXT PRIMARY KEY, title TEXT NOT NULL, author TEXT NOT NULL DEFAULT '', categoryId TEXT NOT NULL REFERENCES category(id) ON DELETE RESTRICT, fileType TEXT NOT NULL CHECK (fileType IN ('pdf','markdown')), fileHash TEXT NOT NULL UNIQUE, originalFilename TEXT NOT NULL, originalBookmark BLOB, storedPath TEXT NOT NULL, pageCount INTEGER, coverPath TEXT, coverSource TEXT NOT NULL DEFAULT 'default' CHECK (coverSource IN ('default','custom','page')), extractionStatus TEXT NOT NULL DEFAULT 'pending' CHECK (extractionStatus IN ('pending','done','failed')), extractionVersion INTEGER NOT NULL DEFAULT 0, pdfPosition TEXT, textPosition INTEGER, progress REAL NOT NULL DEFAULT 0, addedAt REAL NOT NULL, lastOpenedAt REAL )
table|documentNote|documentNote|CREATE TABLE documentNote ( documentId TEXT PRIMARY KEY REFERENCES document(id) ON DELETE CASCADE, body TEXT NOT NULL DEFAULT '', updatedAt REAL NOT NULL)
table|documentNote_fts|documentNote_fts|CREATE VIRTUAL TABLE documentNote_fts USING fts5(body, content='documentNote', tokenize='studyreader')
table|documentNote_fts_config|documentNote_fts_config|CREATE TABLE 'documentNote_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID
table|documentNote_fts_data|documentNote_fts_data|CREATE TABLE 'documentNote_fts_data'(id INTEGER PRIMARY KEY, block BLOB)
table|documentNote_fts_docsize|documentNote_fts_docsize|CREATE TABLE 'documentNote_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)
table|documentNote_fts_idx|documentNote_fts_idx|CREATE TABLE 'documentNote_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID
table|documentTag|documentTag|CREATE TABLE documentTag ( documentId TEXT NOT NULL REFERENCES document(id) ON DELETE CASCADE, tagId TEXT NOT NULL REFERENCES tag(id) ON DELETE CASCADE, PRIMARY KEY (documentId, tagId))
table|documentText|documentText|CREATE TABLE documentText ( documentId TEXT NOT NULL REFERENCES document(id) ON DELETE CASCADE, unitIndex INTEGER NOT NULL, startOffset INTEGER NOT NULL, text TEXT NOT NULL, runs TEXT, PRIMARY KEY (documentId, unitIndex) )
table|documentText_fts|documentText_fts|CREATE VIRTUAL TABLE documentText_fts USING fts5(text, content='documentText', tokenize='studyreader')
table|documentText_fts_config|documentText_fts_config|CREATE TABLE 'documentText_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID
table|documentText_fts_data|documentText_fts_data|CREATE TABLE 'documentText_fts_data'(id INTEGER PRIMARY KEY, block BLOB)
table|documentText_fts_docsize|documentText_fts_docsize|CREATE TABLE 'documentText_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)
table|documentText_fts_idx|documentText_fts_idx|CREATE TABLE 'documentText_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID
table|document_fts|document_fts|CREATE VIRTUAL TABLE document_fts USING fts5(title, author, content='document', tokenize='studyreader')
table|document_fts_config|document_fts_config|CREATE TABLE 'document_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID
table|document_fts_data|document_fts_data|CREATE TABLE 'document_fts_data'(id INTEGER PRIMARY KEY, block BLOB)
table|document_fts_docsize|document_fts_docsize|CREATE TABLE 'document_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)
table|document_fts_idx|document_fts_idx|CREATE TABLE 'document_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID
table|exportTarget|exportTarget|CREATE TABLE exportTarget ( id TEXT PRIMARY KEY, title TEXT NOT NULL, scope TEXT NOT NULL, options TEXT NOT NULL, googleFileId TEXT, googleFolderId TEXT, format TEXT NOT NULL DEFAULT 'markdown' CHECK (format IN ('markdown','html')), keepInSync INTEGER NOT NULL DEFAULT 0, lastExportedAt REAL, lastStatus TEXT NOT NULL DEFAULT 'never', lastError TEXT, createdAt REAL NOT NULL)
table|highlight|highlight|CREATE TABLE highlight ( id TEXT PRIMARY KEY, documentId TEXT NOT NULL REFERENCES document(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('text','image')), view TEXT NOT NULL CHECK (view IN ('pdf','text','markdown')), color INTEGER NOT NULL DEFAULT 0 CHECK (color BETWEEN 0 AND 4), text TEXT NOT NULL DEFAULT '', richText TEXT NOT NULL DEFAULT '', editedText TEXT, note TEXT NOT NULL DEFAULT '', pageIndex INTEGER, positionKey REAL NOT NULL, anchor TEXT NOT NULL, anchorStatus TEXT NOT NULL DEFAULT 'ok' CHECK (anchorStatus IN ('ok','orphaned')), imagePath TEXT, createdAt REAL NOT NULL, updatedAt REAL NOT NULL )
table|highlightEmbedding|highlightEmbedding|CREATE TABLE highlightEmbedding ( highlightId TEXT PRIMARY KEY REFERENCES highlight(id) ON DELETE CASCADE, modelId TEXT NOT NULL, dimension INTEGER NOT NULL, vector BLOB NOT NULL, sourceHash TEXT NOT NULL)
table|highlightTag|highlightTag|CREATE TABLE highlightTag ( highlightId TEXT NOT NULL REFERENCES highlight(id) ON DELETE CASCADE, tagId TEXT NOT NULL REFERENCES tag(id) ON DELETE CASCADE, PRIMARY KEY (highlightId, tagId))
table|highlight_fts|highlight_fts|CREATE VIRTUAL TABLE highlight_fts USING fts5(text, editedText, note, content='highlight', tokenize='studyreader')
table|highlight_fts_config|highlight_fts_config|CREATE TABLE 'highlight_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID
table|highlight_fts_data|highlight_fts_data|CREATE TABLE 'highlight_fts_data'(id INTEGER PRIMARY KEY, block BLOB)
table|highlight_fts_docsize|highlight_fts_docsize|CREATE TABLE 'highlight_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB)
table|highlight_fts_idx|highlight_fts_idx|CREATE TABLE 'highlight_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID
table|reviewCard|reviewCard|CREATE TABLE reviewCard ( id TEXT PRIMARY KEY, highlightId TEXT NOT NULL REFERENCES highlight(id) ON DELETE CASCADE, cardType TEXT NOT NULL CHECK (cardType IN ('passive','cloze','qa')), clozeRanges TEXT, question TEXT, answer TEXT, fsrsCard TEXT NOT NULL, dueAt REAL NOT NULL, state TEXT NOT NULL, frequencyOverride TEXT CHECK (frequencyOverride IN ('off','low','normal','high')), suspended INTEGER NOT NULL DEFAULT 0, suspendedReason TEXT CHECK (suspendedReason IN ('mastery','frequencyOff','user')), introducedAt REAL, createdAt REAL NOT NULL)
table|reviewLog|reviewLog|CREATE TABLE reviewLog ( id TEXT PRIMARY KEY, cardId TEXT NOT NULL REFERENCES reviewCard(id) ON DELETE CASCADE, rating INTEGER NOT NULL, reviewedAt REAL NOT NULL, sessionKind TEXT NOT NULL CHECK (sessionKind IN ('daily','themed')), themedReviewId TEXT REFERENCES themedReview(id) ON DELETE SET NULL, fsrsLog TEXT NOT NULL)
table|tag|tag|CREATE TABLE tag (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE COLLATE NOCASE, createdAt REAL NOT NULL)
table|themedReview|themedReview|CREATE TABLE themedReview ( id TEXT PRIMARY KEY, name TEXT NOT NULL, filter TEXT NOT NULL, cardsPerSession INTEGER NOT NULL DEFAULT 20, interval TEXT NOT NULL, orderMode TEXT NOT NULL DEFAULT 'dueFirst' CHECK (orderMode IN ('dueFirst','random')), lastCompletedAt REAL, createdAt REAL NOT NULL)
trigger|documentNote_fts_ad|documentNote|CREATE TRIGGER documentNote_fts_ad AFTER DELETE ON documentNote BEGIN INSERT INTO documentNote_fts(documentNote_fts, rowid, body) VALUES ('delete', old.rowid, old.body); END
trigger|documentNote_fts_ai|documentNote|CREATE TRIGGER documentNote_fts_ai AFTER INSERT ON documentNote BEGIN INSERT INTO documentNote_fts(rowid, body) VALUES (new.rowid, new.body); END
trigger|documentNote_fts_au|documentNote|CREATE TRIGGER documentNote_fts_au AFTER UPDATE OF body ON documentNote BEGIN INSERT INTO documentNote_fts(documentNote_fts, rowid, body) VALUES ('delete', old.rowid, old.body); INSERT INTO documentNote_fts(rowid, body) VALUES (new.rowid, new.body); END
trigger|documentText_fts_ad|documentText|CREATE TRIGGER documentText_fts_ad AFTER DELETE ON documentText BEGIN INSERT INTO documentText_fts(documentText_fts, rowid, text) VALUES ('delete', old.rowid, old.text); END
trigger|documentText_fts_ai|documentText|CREATE TRIGGER documentText_fts_ai AFTER INSERT ON documentText BEGIN INSERT INTO documentText_fts(rowid, text) VALUES (new.rowid, new.text); END
trigger|documentText_fts_au|documentText|CREATE TRIGGER documentText_fts_au AFTER UPDATE OF text ON documentText BEGIN INSERT INTO documentText_fts(documentText_fts, rowid, text) VALUES ('delete', old.rowid, old.text); INSERT INTO documentText_fts(rowid, text) VALUES (new.rowid, new.text); END
trigger|document_fts_ad|document|CREATE TRIGGER document_fts_ad AFTER DELETE ON document BEGIN INSERT INTO document_fts(document_fts, rowid, title, author) VALUES ('delete', old.rowid, old.title, old.author); END
trigger|document_fts_ai|document|CREATE TRIGGER document_fts_ai AFTER INSERT ON document BEGIN INSERT INTO document_fts(rowid, title, author) VALUES (new.rowid, new.title, new.author); END
trigger|document_fts_au|document|CREATE TRIGGER document_fts_au AFTER UPDATE OF title, author ON document BEGIN INSERT INTO document_fts(document_fts, rowid, title, author) VALUES ('delete', old.rowid, old.title, old.author); INSERT INTO document_fts(rowid, title, author) VALUES (new.rowid, new.title, new.author); END
trigger|highlight_fts_ad|highlight|CREATE TRIGGER highlight_fts_ad AFTER DELETE ON highlight BEGIN INSERT INTO highlight_fts(highlight_fts, rowid, text, editedText, note) VALUES ('delete', old.rowid, old.text, old.editedText, old.note); END
trigger|highlight_fts_ai|highlight|CREATE TRIGGER highlight_fts_ai AFTER INSERT ON highlight BEGIN INSERT INTO highlight_fts(rowid, text, editedText, note) VALUES (new.rowid, new.text, new.editedText, new.note); END
trigger|highlight_fts_au|highlight|CREATE TRIGGER highlight_fts_au AFTER UPDATE OF text, editedText, note ON highlight BEGIN INSERT INTO highlight_fts(highlight_fts, rowid, text, editedText, note) VALUES ('delete', old.rowid, old.text, old.editedText, old.note); INSERT INTO highlight_fts(rowid, text, editedText, note) VALUES (new.rowid, new.text, new.editedText, new.note); END
